<script lang="ts">import { enhance } from '$app/forms'; import type { ActionData, PageServerData } from './$types'; let { data, form }: { data: PageServerData; form: ActionData } = $props();</script><svelte:head><title>Reports · LinkGarden admin</title><meta name="robots" content="noindex" /></svelte:head><h1>Content reports</h1>{#if form?.message}<p class="error">{form.message}</p>{/if}{#each data.reports as row}<article class="card"><p class="eyebrow">{row.report.status}</p><h2>{row.linkTitle ?? row.listTitle ?? 'Deleted content'}</h2><p>Reason: {row.report.reason}{row.report.explanation ? ` — ${row.report.explanation}` : ''}</p><p>Reported by {row.reporterUsername ? '@' + row.reporterUsername : 'deleted user'} on {row.report.createdAt.toLocaleString()}.</p>{#if row.report.status === 'open'}<div class="actions"><form method="post" action="?/dismiss" use:enhance><input type="hidden" name="id" value={row.report.id} /><button class="secondary">Dismiss</button></form><form method="post" action="?/hide" use:enhance><input type="hidden" name="id" value={row.report.id} /><button class="danger">Hide content</button></form></div>{:else if (row.report.targetLinkId && row.linkState === 'hidden') || (row.report.targetListId && row.listState === 'hidden')}<form method="post" action="?/restore" use:enhance><input type="hidden" name="type" value={row.report.targetLinkId ? 'link' : 'list'} /><input type="hidden" name="targetId" value={row.report.targetLinkId ?? row.report.targetListId ?? ''} /><button>Restore content</button></form>{/if}</article>{:else}<p>No reports.</p>{/each}
